INSERT INTO ui_translations (`key`, de, en, fr, it, tr, ja, cs, ru, es, nl, pl) VALUES
  ('product.contact.phone_country_hint', 'Bitte wählen Sie zuerst das Land (Vorwahl). Wenn Sie eine Nummer angeben, ist die Vorwahl erforderlich.', 'Please select the country (dialing code) first. If you enter a phone number, the country code is required.', 'Veuillez d’abord choisir le pays (indicatif). Si vous saisissez un numéro, l’indicatif est obligatoire.', 'Seleziona prima il paese (prefisso). Se inserisci un numero, il prefisso internazionale è obbligatorio.', 'Önce ülkeyi (alan kodu) seçin. Numara girerseniz ülke kodu zorunludur.', 'まず国（国番号）を選択してください。電話番号を入力する場合は国番号が必須です。', 'Nejprve vyberte zemi (předvolbu). Zadáte-li číslo, je předvolba povinná.', 'Сначала выберите страну (код). Если вы вводите номер, код страны обязателен.', 'Seleccione primero el país (prefijo). Si introduce un número, el prefijo es obligatorio.', 'Kies eerst het land (netnummer). Als u een nummer invult, is de landcode verplicht.', 'Najpierw wybierz kraj (numer kierunkowy). Jeśli podasz numer, kod kraju jest wymagany.'),
  ('product.contact.country_code', 'Land / Vorwahl', 'Country / dialing code', 'Pays / indicatif', 'Paese / prefisso', 'Ülke / alan kodu', '国 / 国番号', 'Země / předvolba', 'Страна / код', 'País / prefijo', 'Land / netnummer', 'Kraj / numer kierunkowy'),
  ('product.contact.country_select', 'Land wählen …', 'Select country…', 'Choisir le pays…', 'Seleziona il paese…', 'Ülke seçin…', '国を選択…', 'Vyberte zemi…', 'Выберите страну…', 'Seleccione el país…', 'Kies land…', 'Wybierz kraj…'),
  ('product.contact.phone_need_country', 'Bitte wählen Sie für Ihre Telefonnummer ein Land (Vorwahl) aus.', 'Please select a country (dialing code) for your phone number.', 'Veuillez choisir un pays (indicatif) pour votre numéro de téléphone.', 'Seleziona un paese (prefisso) per il tuo numero di telefono.', 'Lütfen telefon numaranız için bir ülke (alan kodu) seçin.', '電話番号の国（国番号）を選択してください。', 'Vyberte prosím zemi (předvolbu) pro své telefonní číslo.', 'Пожалуйста, выберите страну (код) для вашего номера телефона.', 'Seleccione un país (prefijo) para su número de teléfono.', 'Kies een land (netnummer) voor uw telefoonnummer.', 'Wybierz kraj (numer kierunkowy) dla swojego numeru telefonu.'),
